eval(pm.environment.get('pmlib_code') || pm.globals.get('pmlib_code'));

// The token comes back as a Set-Cookie, not in the body: the body carries only
// {status, message} and answers 200 whether or not a token was minted, so a
// green response here proves nothing. The cookie is the only evidence.
var token = null;
pm.response.headers.each(function (h) {
    if (!token && h.key.toLowerCase() === 'set-cookie' && h.value.indexOf('Authorization=') === 0) {
        token = h.value.split(';')[0].substring('Authorization='.length);
    }
});

var body = null;
try { body = pm.response.json(); } catch (e) { body = null; }

pm.test('partner token issued', function () {
    pm.expect(JSON.stringify((body && body.errors) || []), 'authmanager rejected the credentials - partnerSecret is deployment-specific').to.equal('[]');
    pm.expect(token, 'no Authorization cookie in the response').to.be.a('string');
});

if (token) {
    // Cleared before validation, not after: client-mgmt rejects a stale, expired or
    // wrong-scope token exactly as it does a missing one - 'Full authentication is
    // required to access this resource' at HTTP 200 - so a token left behind after
    // failing its checks looks correctly populated while every registration fails.
    pm.environment.unset('authToken');

    var claims = {};
    try {
        var parsed = JSON.parse(pmlib.rs.b64utoutf8(token.split('.')[1]));
        if (parsed && typeof parsed === 'object') claims = parsed;
    } catch (e) {
        // Malformed token: both checks below fail on the empty claims and report it.
    }

    // scope is space-delimited, so membership rather than substring - a scope such as
    // add_oidc_client_readonly must not pass. A token minted for the wrong appId
    // authenticates perfectly and still cannot register a client; its scope is the
    // only thing that says so, and the failure it causes later does not mention it.
    var hasScope = typeof claims.scope === 'string' &&
        claims.scope.split(/\s+/).indexOf('add_oidc_client') !== -1;

    // These tokens are short-lived. Authenticating once and registering some minutes
    // later fails exactly like never authenticating at all.
    var notExpired = typeof claims.exp === 'number' && isFinite(claims.exp) &&
        claims.exp * 1000 > Date.now();

    pm.test('token carries add_oidc_client', function () {
        pm.expect(hasScope, 'wrong appId, or the token could not be decoded - it cannot register clients').to.equal(true);
    });

    pm.test('token is not already expired', function () {
        pm.expect(notExpired, 'authToken has no usable exp, or has already expired - re-run this request immediately before creating the client').to.equal(true);
    });

    // Stored only once both checks pass, so the environment never holds a token that
    // client-mgmt will refuse.
    if (hasScope && notExpired) pm.environment.set('authToken', token);
} else {
    pm.environment.unset('authToken');
}

var body = pm.response.json();
pm.test('csrf token returned', function () {
    pm.expect(body.token).to.be.a('string');
});
pm.environment.set('csrf_token', body.token);

eval(pm.environment.get('pmlib_code') || pm.globals.get('pmlib_code'));

// eSignet can neither re-key a client nor hand its key back, so an existing key pair is
// never overwritten: it is reused. To register a different client, clear privateKey_jwk
// and publicKey_jwk in the environment first.
if (!pm.environment.get('privateKey_jwk') || !pm.environment.get('publicKey_jwk')) {
    var kp = pmlib.rs.KEYUTIL.generateKeypair('RSA', 2048);
    pm.environment.set('privateKey_jwk', JSON.stringify(pmlib.rs.KEYUTIL.getJWK(kp.prvKeyObj)));
    pm.environment.set('publicKey_jwk', JSON.stringify(pmlib.rs.KEYUTIL.getJWK(kp.pubKeyObj)));
}

pm.test("Validate clientId", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData.response.clientId).to.eql(pm.environment.get("clientId"));
});

pm.test("Validate status", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData.response.status).to.eql("ACTIVE");
});

var jsonData = pm.response.json();
var osid = jsonData?.result?.Insurance?.osid;
pm.test('record created', function () {
    pm.expect(osid, JSON.stringify(jsonData)).to.be.a('string');
});
if (osid) pm.collectionVariables.set('insurance_registry_osid', osid);

let req = JSON.parse(pm.request.body.toJSON().raw);

pm.collectionVariables.set("insurance_registry_fullName", req?.fullName);
pm.collectionVariables.set("insurance_registry_dob", req?.dob);
pm.collectionVariables.set("insurance_registry_policyNumber", req?.policyNumber);

var jsonData = pm.response.json();
pm.test('search returned a list', function () {
    pm.expect(jsonData).to.be.an('array');
});

// Two records with the same policyNumber make eSignet's KBI authentication fail with
// auth_failed. Delete the extras with 'Delete by OSID'.
pm.test('exactly one record matches', function () {
    pm.expect(jsonData.length, 'duplicate or missing records for this policyNumber').to.equal(1);
});

var osid = pm.collectionVariables.get('insurance_registry_osid');
var obj = jsonData.find(function (d) { return d && d.osid === osid; }) || jsonData[0] || {};
var registry = Object.keys(obj).reduce(function (res, item) {
    if (!item.startsWith('os')) res[item] = obj[item];
    return res;
}, {});
pm.collectionVariables.set('insurance_registry_expiresOn', registry.policyExpiresOn);
pm.collectionVariables.set('insurance_registry', JSON.stringify(registry));

var body = pm.response.json();
pm.test('csrf token returned', function () {
    pm.expect(body.token).to.be.a('string');
});
pm.environment.set('csrf_token', body.token);

var jsonData = pm.response.json();

pm.test('no errors', function () {
    pm.expect(jsonData.errors, JSON.stringify(jsonData.errors)).to.eql([]);
});

if (jsonData.response) {
    pm.test('transactionId returned', function () {
        pm.expect(jsonData.response.transactionId).to.be.a('string');
    });

    pm.test('KBI auth factor offered', function () {
        var factors = [].concat.apply([], jsonData.response.authFactors || []);
        pm.expect(factors.some(function (f) { return f.type === 'KBI'; }), 'the client or acrValues does not allow KBI').to.equal(true);
    });

    var sha256Hash = CryptoJS.SHA256(JSON.stringify(jsonData.response));
    // base64url, no padding
    var b64u = sha256Hash.toString(CryptoJS.enc.Base64).replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_');
    pm.environment.set('transaction_id', jsonData.response.transactionId);
    pm.environment.set('oauth_details_key', jsonData.response.transactionId);
    pm.environment.set('oauth_details_hash', b64u);
}

eval(pm.environment.get('pmlib_code') || pm.globals.get('pmlib_code'));

const pkce = pmlib.pkceChallenge();
pm.collectionVariables.set('codeChallenge', pkce.code_challenge);
pm.collectionVariables.set('codeChallengeMethod', pkce.code_challenge_method);
pm.collectionVariables.set('codeVerifier', pkce.code_verifier);

// Fresh, unpredictable nonce and state on every run (eSignet answers invalid_request
// to a missing or very short nonce).
pm.environment.set('nonce', CryptoJS.lib.WordArray.random(16).toString());
pm.environment.set('state', CryptoJS.lib.WordArray.random(8).toString());

// KBI challenge = base64url(JSON) of the fields the eSignet lists in
// auth.factor.kbi.field-details. They come from the same collection variables the registry
// record is created from, so the challenge always matches the record.
var fields = {
    policyNumber: pm.collectionVariables.get('insurance_registry_policyNumber'),
    fullName: pm.collectionVariables.get('insurance_registry_fullName'),
    dob: pm.collectionVariables.get('insurance_registry_dob')
};
Object.keys(fields).forEach(function (k) {
    if (!fields[k]) throw new Error('insurance_registry_' + k + ' is empty - set it in the collection variables');
});
var b64 = CryptoJS.enc.Base64.stringify(CryptoJS.enc.Utf8.parse(JSON.stringify(fields)));
pm.collectionVariables.set('kbi_challenge', b64.replace(/=+$/, '').replace(/\+/g, '-').replace(/\//g, '_'));

var jsonData = pm.response.json();
pm.test('authenticated', function () {
    pm.expect(jsonData.errors, JSON.stringify(jsonData.errors) + ' - auth_failed usually means no record, or more than one, matches').to.eql([]);
});

var jsonData = pm.response.json();
pm.test('no errors', function () {
    pm.expect(jsonData.errors, JSON.stringify(jsonData.errors)).to.eql([]);
});
pm.test('code returned', function () {
    pm.expect(jsonData.response.code).to.be.a('string');
});
if (jsonData.response) pm.collectionVariables.set('code', jsonData.response.code);

eval(pm.environment.get('pmlib_code') || pm.globals.get('pmlib_code'));

// The client assertion's aud is the token endpoint of the eSignet being called.
// The key pair was generated and stored by 'Create OIDC client'.
var tokenUrl = pm.environment.get('url') + '/oauth/v2/token';
const signed_jwt = pmlib.clientAssertPrivateKey(JSON.parse(pm.environment.get('privateKey_jwk')), pm.environment.get('clientId'), tokenUrl, 2000, 'RS256');
pm.collectionVariables.set('client_assertion', signed_jwt);

var jsonData = pm.response.json();
pm.test('token response', function () {
    pm.expect(jsonData.access_token, JSON.stringify(jsonData)).to.be.a('string');
    pm.expect(jsonData.id_token).to.be.a('string');
});
if (jsonData.access_token) pm.environment.set('access_token', jsonData.access_token);

var response = pm.response.json();
pm.test('c_nonce issued', function () {
    pm.expect(response.c_nonce).to.be.a('string');
});
pm.environment.set('c_nonce', response.c_nonce);

eval(pm.environment.get('pmlib_code') || pm.globals.get('pmlib_code'));

// A fresh holder key pair per run; the proof JWT binds the credential to it.
var keyPair = pmlib.rs.KEYUTIL.generateKeypair('RSA', 2048);
var jwkPrivateKey = pmlib.rs.KEYUTIL.getJWK(keyPair.prvKeyObj);
var jwkPublicKey = pmlib.rs.KEYUTIL.getJWK(keyPair.pubKeyObj);
jwkPublicKey['alg'] = 'RS256';
jwkPublicKey['use'] = 'sig';

pm.environment.set('holder_public_key', JSON.stringify(jwkPublicKey));
pm.environment.set('holder_private_key', JSON.stringify(jwkPrivateKey));

var header = {
    'alg': 'RS256',
    'typ': 'openid4vci-proof+jwt',
    'jwk': jwkPublicKey
};

// iss must equal the access token's client_id; aud must equal certify's credential_issuer.
const signed_jwt = pmlib.jwtSign(jwkPrivateKey, {
    'aud': pm.environment.get('audUrl'),
    'nonce': pm.environment.get('c_nonce'),
    'iss': pm.environment.get('clientId')
}, header, 600, 'RS256');
pm.collectionVariables.set('proof_jwt', signed_jwt);

var jsonData = pm.response.json();
pm.test('status is 200', function () {
    pm.response.to.have.status(200);
});
pm.test('a credential came back', function () {
    pm.expect(jsonData.credentials || jsonData.credential, JSON.stringify(jsonData)).to.exist;
});
if (jsonData.c_nonce) pm.environment.set('c_nonce', jsonData.c_nonce);

